import type { Context } from "hono"

import consola from "consola"
import { type SSEMessage } from "hono/streaming"

import { awaitApproval } from "~/lib/approval"
import { resolveEffort } from "~/lib/effort"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { checkRateLimit } from "~/lib/rate-limit"
import { state } from "~/lib/state"
import { streamSSEWithAbort, writeOpenAIStreamError } from "~/lib/streaming"
import { getTokenCount } from "~/lib/tokenizer"
import { isNullish } from "~/lib/utils"
import {
  createChatCompletions,
  type ChatCompletionChunk,
  type ChatCompletionsPayload,
} from "~/services/copilot/create-chat-completions"
import {
  createResponses,
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"

export async function handleCompletion(c: Context) {
  await checkRateLimit(state)

  let payload = await c.req.json<ChatCompletionsPayload>()
  consola.debug("Request payload:", JSON.stringify(payload).slice(-400))

  // Find the selected model
  const selectedModel = state.models?.data.find(
    (model) => model.id === payload.model,
  )

  // Calculate and display token count
  try {
    if (selectedModel) {
      const tokenCount = await getTokenCount(payload, selectedModel)
      consola.info("Current token count:", tokenCount)
    } else {
      consola.warn("No model selected, skipping token count calculation")
    }
  } catch (error) {
    consola.warn("Failed to calculate token count:", error)
  }

  if (state.manualApprove) await awaitApproval()

  // Upstream rejects a request carrying both token controls, so only supply a
  // catalog default when the client expressed neither.
  const hasClientTokenLimit =
    !isNullish(payload.max_tokens) || !isNullish(payload.max_completion_tokens)

  if (!hasClientTokenLimit) {
    payload = {
      ...payload,
      max_tokens: selectedModel?.capabilities.limits.max_output_tokens,
    }
    consola.debug("Set max_tokens to:", JSON.stringify(payload.max_tokens))
  }

  const endpoint = resolveEndpoint(payload.model, state.models)
  const signal = c.req.raw.signal

  // Route to /responses for GPT-5.x and models that only support it
  if (endpoint === "/responses") {
    consola.debug(`Using /responses endpoint for model: ${payload.model}`)
    return handleResponsesEndpoint(c, payload, signal)
  }

  payload.reasoning_effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
  })

  // Existing /chat/completions path
  const result = await createChatCompletions(payload, signal)

  if (result.kind === "object") {
    consola.debug("Non-streaming response:", JSON.stringify(result.body))
    return c.json(result.body)
  }
  const response = result.stream

  consola.debug("Streaming response")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "chat-completions",
      onError: writeOpenAIStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      for await (const chunk of response) {
        consola.debug("Streaming chunk:", JSON.stringify(chunk))
        terminalErrorSeen ||= Boolean((chunk as ChatCompletionChunk).error)
        await stream.writeSSE(chunk as SSEMessage)
      }
    },
  )
}

async function handleResponsesEndpoint(
  c: Context,
  payload: ChatCompletionsPayload,
  signal?: AbortSignal,
) {
  const effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
    defaultEffort: "medium",
  })
  const result = await createResponses(payload, effort, signal)

  if (result.kind === "object") {
    consola.debug(
      "Non-streaming /responses result:",
      JSON.stringify(result.body),
    )
    return c.json(result.body)
  }
  const response = result.stream

  consola.debug("Streaming /responses response")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "/responses",
      onError: writeOpenAIStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      const streamState = createResponsesStreamState()

      for await (const rawEvent of response) {
        if (!rawEvent.data || rawEvent.data === "[DONE]") continue

        const parsed = JSON.parse(rawEvent.data) as Record<string, unknown>
        const eventType =
          rawEvent.event ?? (parsed.type as string | undefined) ?? ""

        const chunks = translateResponsesStreamEvent(
          { event: eventType, data: parsed },
          streamState,
        )

        for (const chunk of chunks) {
          consola.debug("Translated /responses chunk:", JSON.stringify(chunk))
          terminalErrorSeen ||= Boolean(chunk.error)
          await stream.writeSSE({
            data: JSON.stringify(chunk),
          })
        }
      }
    },
  )
}

import consola from "consola"
import { events } from "fetch-event-stream"

import type { CopilotUsage, RawCopilotUsage } from "~/lib/copilot-usage"
import type { RequestedEffort } from "~/lib/effort"

import { copilotBaseUrl } from "~/lib/api-config"
import { copilotFetch } from "~/lib/copilot-fetch"
import { normalizeCopilotUsage } from "~/lib/copilot-usage"
import { HTTPError } from "~/lib/error"
import { state } from "~/lib/state"

import {
  objectResult,
  type ServiceResult,
  streamResult,
} from "./service-result"

export type ChatCompletionStream = ReturnType<typeof events>

export const createChatCompletions = async (
  payload: ChatCompletionsPayload,
  signal?: AbortSignal,
): Promise<ServiceResult<ChatCompletionResponse, ChatCompletionStream>> => {
  if (!state.copilotToken) throw new Error("Copilot token not found")

  const enableVision = payload.messages.some(
    (x) =>
      typeof x.content !== "string"
      && x.content?.some((x) => x.type === "image_url"),
  )

  // Agent/user check for X-Initiator header
  // Determine if any message is from an agent ("assistant" or "tool")
  const isAgentCall = payload.messages.some((msg) =>
    ["assistant", "tool"].includes(msg.role),
  )

  // Build headers and add X-Initiator
  const response = await copilotFetch(
    `${copilotBaseUrl(state)}/chat/completions`,
    {
      method: "POST",
      headers: { "X-Initiator": isAgentCall ? "agent" : "user" },
      body: JSON.stringify(payload),
      signal,
    },
    { vision: enableVision },
  )

  if (!response.ok) {
    consola.error("Failed to create chat completions", response)
    throw new HTTPError("Failed to create chat completions", response)
  }

  if (payload.stream) {
    return streamResult(events(response))
  }

  const result = (await response.json()) as ChatCompletionResponse & {
    copilot_usage?: RawCopilotUsage
  }
  result.copilot_usage = normalizeCopilotUsage(result.copilot_usage)
  return objectResult(result)
}

// Streaming types

export interface ChatCompletionChunk {
  id: string
  object: "chat.completion.chunk"
  created: number
  model: string
  choices: Array<Choice>
  system_fingerprint?: string
  usage?: {
    prompt_tokens: number
    completion_tokens: number
    total_tokens: number
    prompt_tokens_details?: {
      cached_tokens: number
    }
    completion_tokens_details?: {
      accepted_prediction_tokens: number
      rejected_prediction_tokens: number
    }
  }
  error?: {
    type: string
    message: string
    code?: string
  }
}

interface Delta {
  content?: string | null
  refusal?: string | null
  role?: "user" | "assistant" | "system" | "tool"
  tool_calls?: Array<{
    index: number
    id?: string
    type?: "function"
    function?: {
      name?: string
      arguments?: string
    }
  }>
}

interface Choice {
  index: number
  delta: Delta
  finish_reason: "stop" | "length" | "tool_calls" | "content_filter" | null
  logprobs: object | null
}

// Non-streaming types

export interface ChatCompletionResponse {
  id: string
  object: "chat.completion"
  created: number
  model: string
  choices: Array<ChoiceNonStreaming>
  system_fingerprint?: string
  copilot_usage?: CopilotUsage
  usage?: {
    prompt_tokens: number
    completion_tokens: number
    total_tokens: number
    prompt_tokens_details?: {
      cached_tokens: number
    }
  }
}

interface ResponseMessage {
  role: "assistant"
  content: string | null
  refusal?: string | null
  reasoning_text?: string | null
  tool_calls?: Array<ToolCall>
}

interface ChoiceNonStreaming {
  index: number
  message: ResponseMessage
  logprobs: object | null
  finish_reason: "stop" | "length" | "tool_calls" | "content_filter"
}

// Payload types

export interface ChatCompletionsPayload {
  messages: Array<Message>
  model: string
  temperature?: number | null
  top_p?: number | null
  max_tokens?: number | null
  /**
   * Newer clients (VS Code Copilot Chat with thinking enabled) send this
   * instead of max_tokens. Upstream rejects a request carrying both.
   */
  max_completion_tokens?: number | null
  stop?: string | Array<string> | null
  n?: number | null
  stream?: boolean | null

  frequency_penalty?: number | null
  presence_penalty?: number | null
  logit_bias?: Record<string, number> | null
  logprobs?: boolean | null
  response_format?: { type: "json_object" } | null
  seed?: number | null
  reasoning_effort?: RequestedEffort
  tools?: Array<Tool> | null
  tool_choice?:
    | "none"
    | "auto"
    | "required"
    | { type: "function"; function: { name: string } }
    | null
  user?: string | null
}

export interface Tool {
  type: "function"
  function: {
    name: string
    description?: string
    parameters: Record<string, unknown>
  }
}

export interface Message {
  role: "user" | "assistant" | "system" | "tool" | "developer"
  content: string | Array<ContentPart> | null

  name?: string
  tool_calls?: Array<ToolCall>
  tool_call_id?: string
}

export interface ToolCall {
  id: string
  type: "function"
  function: {
    name: string
    arguments: string
  }
}

export type ContentPart = TextPart | ImagePart | AudioPart

export interface TextPart {
  type: "text"
  text: string
}

export interface ImagePart {
  type: "image_url"
  image_url: {
    url: string
    detail?: "low" | "high" | "auto"
  }
}

export interface AudioPart {
  type: "input_audio"
  input_audio: {
    data: string
    format: "wav" | "mp3"
  }
}

import { afterEach, beforeEach, describe, expect, it, mock } from "bun:test"

import { state } from "~/lib/state"
import { server } from "~/server"

const originalFetch = globalThis.fetch

/**
 * Upstream rejects a request that carries both max_tokens and
 * max_completion_tokens with HTTP 400, so the catalog default must only be
 * injected when the client expressed no token control at all. Measured live on
 * claude-opus-4.6: each control alone succeeds, neither succeeds, both fail.
 */
beforeEach(() => {
  state.copilotToken = "test-token"
  state.models = {
    object: "list",
    data: [
      {
        id: "chat-model",
        name: "Chat Model",
        object: "model",
        vendor: "anthropic",
        version: "1",
        preview: false,
        model_picker_enabled: true,
        supported_endpoints: ["/chat/completions"],
        capabilities: {
          family: "claude",
          limits: { max_output_tokens: 4096 },
          object: "model_capabilities",
          supports: {},
          tokenizer: "test",
          type: "chat",
        },
      },
    ],
  }
})

afterEach(() => {
  globalThis.fetch = originalFetch
  state.models = undefined
})

async function captureUpstreamPayload(body: Record<string, unknown>) {
  let captured: Record<string, unknown> | undefined
  globalThis.fetch = mock(
    (_input: string | URL | Request, init?: RequestInit) => {
      if (typeof init?.body !== "string") throw new Error("Expected JSON body")
      captured = JSON.parse(init.body) as Record<string, unknown>
      return Promise.resolve(
        Response.json({ id: "1", object: "chat.completion", choices: [] }),
      )
    },
  ) as unknown as typeof fetch

  const response = await server.request("/v1/chat/completions", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      model: "chat-model",
      messages: [{ role: "user", content: "hi" }],
      ...body,
    }),
  })

  return { status: response.status, payload: captured }
}

describe("chat token limit injection", () => {
  it("injects the catalog default when the client sends neither control", async () => {
    const { payload } = await captureUpstreamPayload({})
    expect(payload?.max_tokens).toBe(4096)
    expect(payload).not.toHaveProperty("max_completion_tokens")
  })

  it("keeps a client max_tokens unchanged", async () => {
    const { payload } = await captureUpstreamPayload({ max_tokens: 128 })
    expect(payload?.max_tokens).toBe(128)
    expect(payload).not.toHaveProperty("max_completion_tokens")
  })

  it("does not inject max_tokens alongside a client max_completion_tokens", async () => {
    const { payload } = await captureUpstreamPayload({
      max_completion_tokens: 128,
    })
    expect(payload?.max_completion_tokens).toBe(128)
    expect(payload).not.toHaveProperty("max_tokens")
  })

  it("does not inject when max_tokens is explicitly null but max_completion_tokens is set", async () => {
    const { payload } = await captureUpstreamPayload({
      max_tokens: null,
      max_completion_tokens: 128,
    })
    expect(payload?.max_completion_tokens).toBe(128)
    expect(payload?.max_tokens).toBeNull()
  })

  it("forwards both controls unchanged when the client sends both", async () => {
    const { payload } = await captureUpstreamPayload({
      max_tokens: 64,
      max_completion_tokens: 128,
    })
    expect(payload?.max_tokens).toBe(64)
    expect(payload?.max_completion_tokens).toBe(128)
  })

  it("never emits both controls when the client sent only one", async () => {
    for (const body of [{ max_tokens: 128 }, { max_completion_tokens: 128 }]) {
      const { payload } = await captureUpstreamPayload(body)
      const emitted = [
        payload?.max_tokens,
        payload?.max_completion_tokens,
      ].filter((value) => value !== undefined && value !== null)
      expect(emitted).toHaveLength(1)
    }
  })

  it("applies the same rule to streaming requests", async () => {
    const { payload } = await captureUpstreamPayload({
      max_completion_tokens: 128,
      stream: false,
    })
    expect(payload).not.toHaveProperty("max_tokens")
  })
})
